[{"order":1,"type":"heading","text":"Angular Module Organization: Feature, Shared, and Core Modules"},{"order":2,"type":"paragraph","text":"Structuring your Angular application with a well-defined module organization is crucial for maintainability, scalability, and overall code quality. This tutorial explores the common patterns of using Feature Modules, Shared Modules, and a Core Module to achieve a robust architecture."},{"order":3,"type":"subheading","text":"Feature Modules"},{"order":4,"type":"paragraph","text":"Feature modules are designed to encapsulate specific functionalities or sections of your application. Each feature module should focus on a single, well-defined area, such as user management, product catalog, or order processing. This promotes modularity and allows for independent development and testing."},{"order":5,"type":"bullet_point","text":"Encapsulate related components, services, and directives."},{"order":6,"type":"bullet_point","text":"Promote code reusability within the feature."},{"order":7,"type":"bullet_point","text":"Enable lazy loading for improved initial load time (optional)."},{"order":8,"type":"code","text":"// Example: User Management Feature Module (user.module.ts)
import { NgModule } from '@angular/core';
import { CommonModule } from '@angular/common';
import { UserListComponent } from './user-list/user-list.component';
import { UserDetailComponent } from './user-detail/user-detail.component';

@NgModule({
  declarations: [UserListComponent, UserDetailComponent],
  imports: [CommonModule],
  exports: [UserListComponent]
})
export class UserModule { }"},{"order":9,"type":"subheading","text":"Shared Module"},{"order":10,"type":"paragraph","text":"The Shared Module contains reusable components, directives, and pipes that are used across multiple feature modules. This avoids code duplication and promotes consistency throughout the application. Examples include UI components like buttons, input fields, and dialogs, as well as utility pipes and directives."},{"order":11,"type":"bullet_point","text":"Contains reusable UI components (e.g., buttons, input fields)."},{"order":12,"type":"bullet_point","text":"Includes utility pipes and directives."},{"order":13,"type":"bullet_point","text":"Exports all declared components, directives, and pipes."},{"order":14,"type":"bullet_point","text":"Imports `CommonModule` to provide common directives like `*ngIf` and `*ngFor`."},{"order":15,"type":"code","text":"// Example: Shared Module (shared.module.ts)
import { NgModule } from '@angular/core';
import { CommonModule } from '@angular/common';
import { ButtonComponent } from './button/button.component';
import { InputFieldComponent } from './input-field/input-field.component';
import { MyCustomPipe } from './my-custom.pipe';

@NgModule({
  declarations: [ButtonComponent, InputFieldComponent, MyCustomPipe],
  imports: [CommonModule],
  exports: [ButtonComponent, InputFieldComponent, MyCustomPipe, CommonModule]
})
export class SharedModule { }"},{"order":16,"type":"paragraph","text":"Note: The `CommonModule` is re-exported from the `SharedModule` to avoid having to import it in every feature module that uses components from the `SharedModule`."},{"order":17,"type":"subheading","text":"Core Module"},{"order":18,"type":"paragraph","text":"The Core Module is responsible for application-wide services and configurations that should only be instantiated once. This includes services like authentication, data storage, and error handling. The Core Module should only be imported by the AppModule."},{"order":19,"type":"bullet_point","text":"Contains singleton services (e.g., authentication, data storage)."},{"order":20,"type":"bullet_point","text":"Provides global configurations."},{"order":21,"type":"bullet_point","text":"Guarded against multiple imports to prevent creating multiple instances of singleton services."},{"order":22,"type":"code","text":"// Example: Core Module (core.module.ts)
import { NgModule, Optional, SkipSelf } from '@angular/core';
import { AuthService } from './auth.service';

@NgModule({
  providers: [AuthService]
})
export class CoreModule {
  constructor(@Optional() @SkipSelf() parentModule: CoreModule) {
    if (parentModule) {
      throw new Error(
        'CoreModule is already loaded. Import it in the AppModule only'
      );
    }
  }
}"},{"order":23,"type":"paragraph","text":"The constructor in the CoreModule throws an error if the module is imported more than once. This prevents accidental multiple instantiations of singleton services."},{"order":24,"type":"subheading","text":"Importing Modules"},{"order":25,"type":"paragraph","text":"Feature modules import the Shared Module to use its components, directives, and pipes. The AppModule imports the Core Module. Feature modules are typically lazy-loaded or eagerly loaded into the AppModule."},{"order":26,"type":"code","text":"// Example: Importing SharedModule in a Feature Module
import { NgModule } from '@angular/core';
import { CommonModule } from '@angular/common';
import { SharedModule } from '../shared/shared.module';
import { MyFeatureComponent } from './my-feature.component';

@NgModule({
  declarations: [MyFeatureComponent],
  imports: [CommonModule, SharedModule],
  exports: [MyFeatureComponent]
})
export class MyFeatureModule { }"},{"order":27,"type":"subheading","text":"Benefits of Module Organization"},{"order":28,"type":"bullet_point","text":"Improved code organization and maintainability."},{"order":29,"type":"bullet_point","text":"Increased code reusability."},{"order":30,"type":"bullet_point","text":"Enhanced scalability and testability."},{"order":31,"type":"bullet_point","text":"Faster initial load time through lazy loading (for feature modules)."},{"order":32,"type":"paragraph","text":"By following these guidelines for module organization, you can create a more structured, maintainable, and scalable Angular application."}]
